function makeOA(level,subject,index=1){
 const t=STAGE_TEMPLATES[level.track]||STAGE_TEMPLATES.Básica;
 const tp=level.track==='Técnico-Profesional'?' · competencia vinculada a especialidad':'';
 return {id:`DEMO-${level.id}-${subject.replace(/[^A-Za-zÁÉÍÓÚÑáéíóúñ]/g,'').slice(0,5).toUpperCase()}-${index}`,level:level.name,levelId:level.id,stage:level.stage,track:level.track,subject,unit:index===1?'Unidad / eje 1':'Unidad / eje 2',official:false,
  objective:index===1?`OA DEMO 1 · ${level.name} · ${subject}${tp}: comprender y aplicar conocimientos, habilidades y actitudes en una situación contextualizada y observable.`:`OA DEMO 2 · ${level.name} · ${subject}${tp}: analizar, comunicar y transferir el aprendizaje a una tarea auténtica, justificando decisiones y resultados.`,
  content:t.content,competencies:t.competencies,indicators:t.indicators,instruments:t.instruments,
  strategy:'Modelado breve, práctica guiada, colaboración y retroalimentación formativa.',
  phases:{start:'Activación de conocimientos previos, propósito y criterios de éxito.',development:'Experiencia central con andamiaje, trabajo colaborativo y monitoreo.',closure:'Síntesis, metacognición y evidencia breve de aprendizaje.'},
  resources:['Presentación breve','Guía/organizador','Material concreto o digital','Recurso audiovisual'],timeSpace:'90 min · aula flexible con momentos individual, parejas y plenario',source:'Estructura DEMO preparada para importación versionada desde Currículum Nacional (Mineduc)'};
}
