function save(){localStorage.setItem('ecosistema41_demo',JSON.stringify(db));}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function initials(n=''){return n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function now(){return new Date().toLocaleString('es-CL',{dateStyle:'short',timeStyle:'short'});}
function cfg(){return PROFILE_CONFIG[db.user?.profile||'docente'];}
function can(r){return cfg().routes.includes(r);}
function go(r){if(!can(r)){alert('Este perfil no tiene acceso a ese módulo en la DEMO.');return;}route=r;render();}
function profileClass(){return `role-${cfg().accent}`;}

function loginView(){return `<div class="login"><section class="loginHero"><div class="brandLock"><div class="brandMark"></div><div class="brandText"><b>ECOSISTEMA EDUCATIVO 4.2</b><small>Libro · Currículum · Evaluación · Inclusión · Convivencia · Familia</small></div></div><div class="heroCopy"><span class="eyebrow">DEMO AVANZADA · COMUNIDAD EDUCATIVA COMPLETA</span><h1>Una plataforma.<br><span>Un rol, tareas claras.</span></h1><p>El ecosistema adapta la experiencia a cada integrante de la comunidad. Docencia trabaja con currículum y evaluación; PIE con apoyos y PACI; UTP con cobertura y acompañamiento; Inspectoría con operación y protocolos; Convivencia con prevención; la familia con información exclusiva de sus hijos.</p><div class="heroPills"><span class="heroPill">📘 Libro físico-digital</span><span class="heroPill">🎯 OA + competencias</span><span class="heroPill">🧩 PIE / DUA / PACI</span><span class="heroPill">🛡️ Inspectoría</span><span class="heroPill">🤝 Convivencia</span><span class="heroPill">📕 Libreta del estudiante</span></div></div><div style="font-size:11px;color:#b8cad8;position:relative;z-index:2">Versión de prueba · datos ficticios · permisos demostrativos de frontend</div></section><section class="loginPane"><div class="loginCard"><span class="eyebrow">Acceso DEMO</span><h2>Entrar al Ecosistema 4.2</h2><p class="muted">Selecciona un perfil: el menú y las tareas cambian automáticamente.</p><label>Correo</label><input id="email" class="field" value="usuario@demo.cl"><label>Clave</label><input id="pass" type="password" class="field" value="demo123"><label>Perfil</label><select id="role" class="field"><option value="sostenedor">Sostenedor</option><option value="docente" selected>Docente</option><option value="diferencial">Educadora diferencial</option><option value="utp">U.T.P.</option><option value="inspectoria">Inspectoría General</option><option value="convivencia">Convivencia educativa</option><option value="apoderado">Apoderado / Tutor</option></select><button class="btn primary full" style="margin-top:18px" onclick="login()">Ingresar a la DEMO</button><div class="demoNote"><b>Clave:</b> demo123.<br>El catálogo curricular cubre todos los niveles en la navegación y contiene OA de demostración estructurados. La carga íntegra de OA oficiales debe hacerse desde un catálogo versionado del Mineduc.</div></div></section></div>`;}
function login(){if(document.getElementById('pass').value!=='demo123')return alert('Usa la clave demo123');const profile=document.getElementById('role').value;db.user={profile,name:PROFILE_CONFIG[profile].name,email:document.getElementById('email').value};route=PROFILE_CONFIG[profile].home;save();render();}
function logout(){db.user=null;save();render();}

function navHtml(){const grouped={};cfg().routes.filter(r=>r!=='inicio').forEach(r=>{const g=ROUTES[r][2];(grouped[g]??=[]).push(r)});return `<aside class="sidebar"><div class="sideBrand"><div class="brandMark"></div><div class="brandText"><b>Ecosistema 4.2</b><small>${cfg().label}</small></div></div><div class="navGroup"><button class="navItem ${route==='inicio'?'active':''}" onclick="go('inicio')"><span class="navIcon">⌂</span><span class="navText">Inicio</span></button></div>${Object.entries(grouped).map(([g,rs])=>`<div class="navGroup"><div class="navLabel">${g}</div>${rs.map(r=>`<button class="navItem ${route===r?'active':''}" onclick="go('${r}')"><span class="navIcon">${ROUTES[r][0]}</span><span class="navText">${ROUTES[r][1]}</span></button>`).join('')}</div>`).join('')}<div class="sideFoot">DEMO 4.0 · datos ficticios<br>Los permisos reales deben validarse server-side.<br><button class="navItem" onclick="logout()"><span class="navIcon">↪</span><span class="navText">Cerrar sesión</span></button></div></aside>`;}
function shell(){return `<div class="shell ${profileClass()}">${navHtml()}<main class="main"><header class="topbar"><div class="crumb"><b>${ROUTES[route]?.[1]||'Ecosistema 4.2'}</b><small>${cfg().tag}</small></div><div class="topActions"><span class="sync"><i></i> Sincronizado</span><button class="btn small" onclick="resetDemo()">Reiniciar DEMO</button><div class="user"><div class="avatar">${initials(db.user.name)}</div><div class="utxt"><b style="font-size:11px">${db.user.name}</b><small>${cfg().label}</small></div></div></div></header>${pageFor(route)}</main></div>`;}
function render(){document.getElementById('root').innerHTML=db.user?shell():loginView();}
function pageFor(r){const f={inicio:homePage,libro:bookPage,planificador:plannerPage,curriculum:curriculumPage,evaluaciones:evaluationPage,corrector:correctorPage,recursos:resourcesPage,pie:piePage,utp:utpPage,inspectoria:inspectoriaPage,convivencia:convivenciaPage,protocolos:protocolsPage,rfid:rfidPage,retiros:withdrawalPage,estudiantes:studentsPage,comunidad:communityPage,libreta:libretaPage,familia:familyPage,reportes:reportsPage}[r];return f?f():homePage();}
function roleBanner(title,desc){return `<div class="roleBanner"><div><h2>${title}</h2><p>${desc}</p></div><span class="roleBadge">${cfg().label}</span></div>`;}
function task(icon,title,desc,routeName,button='Abrir'){return `<div class="taskCard"><div class="ticon">${icon}</div><h3>${title}</h3><p>${desc}</p><button class="btn tiny" onclick="go('${routeName}')">${button}</button></div>`;}

function homePage(){const p=db.user.profile;let title='',desc='',tasks='';if(p==='docente'){title='Trabajo docente';desc='La plataforma concentra libro, planificación, OA, evaluación, corrección y recursos en un flujo único.';tasks=[task('📘','Libro de clases','Asistencia, leccionario, evaluaciones y observaciones en formato físico-digital.','libro'),task('🗓️','Planificar desde OA','Contenidos, competencias, indicadores, inicio, desarrollo, cierre, recursos, tiempo y espacio.','planificador'),task('🧪','Crear y corregir','Diseña instrumentos por asignatura y corrige con criterios vinculados al OA.','evaluaciones'),task('🧰','Biblioteca pedagógica','Actividades, presentaciones, guías, videos y material didáctico.','recursos')].join('')}else if(p==='diferencial'){title='Centro de trabajo PIE';desc='Evaluación integral, detección de barreras, co-docencia, DUA, PACI, adecuaciones, apoyo especializado y familia.';tasks=[task('🔎','Evaluación integral','Barreras, antecedentes multidimensionales e instrumentos pedagógicos.','pie'),task('👥','Co-docencia y DUA','Planificación conjunta y enseñanza compartida en aula regular.','planificador'),task('📝','PACI y adecuaciones','Objetivos priorizados, ajustes de acceso y flexibilización de evaluación.','pie'),task('🏠','Vinculación familiar','Entrevistas, orientaciones y registro en libreta del estudiante.','libreta')].join('')}else if(p==='utp'){title='Unidad Técnico Pedagógica';desc='Alineación curricular, revisión de planificaciones, cobertura, acompañamiento docente, evaluación y coordinación PIE.';tasks=[task('🎯','Cobertura curricular','Revisa OA, competencias y avance por nivel/asignatura.','curriculum'),task('🗂️','Supervisar planificaciones','Revisa coherencia, retroalimenta y aprueba planificaciones.','utp'),task('👁️','Acompañamiento de aula','Observaciones, feedback y acuerdos de mejora docente.','utp'),task('✅','Validar instrumentos','Revisa criterios, rúbricas y pruebas antes de aplicar.','evaluaciones')].join('')}else if(p==='inspectoria'){title='Inspectoría General';desc='RIE, asistencia y puntualidad, horarios, reemplazos, retiros, PISE, planta física, recreos y atención a apoderados.';tasks=[task('📡','Asistencia y puntualidad','Revisa asistencia diaria, atrasos e inasistencias reiteradas.','rfid'),task('🚪','Retiro de estudiantes','Autorización, identidad de quien retira, motivo, hora y trazabilidad.','retiros'),task('🚨','Protocolos y RIE','Activa rutas de actuación y registra medidas de resguardo.','protocolos'),task('🛡️','Seguridad y logística','Horarios, reemplazos, PISE, infraestructura y turnos.','inspectoria')].join('')}else if(p==='convivencia'){title='Convivencia educativa';desc='Plan de gestión, participación, prevención, mediación, protocolos, redes externas y apoyo a docentes.';tasks=[task('🫶','Plan de convivencia','Planifica talleres, participación y acciones preventivas.','convivencia'),task('⚠️','Detección temprana','Indicadores de riesgo, exclusión, violencia y ciberacoso.','convivencia'),task('🤝','Mediación','Registra acuerdos restaurativos y seguimientos.','convivencia'),task('🚨','Protocolos','Coordina activación y seguimiento junto a Inspectoría.','protocolos')].join('')}else if(p==='apoderado'){return familyPage(true)}else{title='Control global del sostenedor';desc='Mayor nivel de visibilidad: red de establecimientos, módulos, cumplimiento, inclusión, convivencia y comunidad, manteniendo trazabilidad de accesos.';tasks=[task('▦','Control Tower','Excepciones y cumplimiento de toda la red.','reportes'),task('📘','Libro 3.0','Supervisa evidencia y estado de libros por establecimiento.','libro'),task('📈','UTP y cobertura','Cobertura OA, planificaciones y resultados.','utp'),task('🧩','PIE e inclusión','Seguimiento agregado de apoyos, PACI y co-docencia.','pie')].join('')}
 return `<div class="page">${roleBanner(title,desc)}<div class="heroPanel"><div><span class="eyebrow" style="color:#ffd6dc">ECOSISTEMA EDUCATIVO 4.2</span><h2>La misma información sirve para enseñar, acompañar, gestionar y comunicar.</h2><p>La arquitectura evita registros paralelos: el OA alimenta planificación y evaluación; la asistencia nutre libro e Inspectoría; PIE adapta la experiencia; UTP monitorea; la familia recibe solo lo que corresponde.</p><div class="flow"><span class="flowStep">OA</span><span class="flowArrow">→</span><span class="flowStep">Planificación</span><span class="flowArrow">→</span><span class="flowStep">Clase</span><span class="flowArrow">→</span><span class="flowStep">Evaluación</span><span class="flowArrow">→</span><span class="flowStep">Libro</span><span class="flowArrow">→</span><span class="flowStep">Familia / Gestión</span></div></div><div class="heroQuick"><div class="quick"><b>7</b><small>perfiles especializados</small></div><div class="quick"><b>${LEVELS.length}</b><small>niveles/trayectorias DEMO</small></div><div class="quick"><b>${CURRICULUM.length}</b><small>OA demo estructurados</small></div><div class="quick"><b>1</b><small>fuente de datos compartida</small></div></div></div><h3 style="margin:18px 0 10px">Lo que requiere tu rol</h3><div class="taskGrid">${tasks}</div></div>`;}

function bookPage(){const spreads=[['Identificación del curso','Índice y estructura'],['Nómina del curso','Datos de contacto'],['Asistencia mensual','Asistencia mensual'],['Leccionario','Registro de contenidos'],['Evaluaciones','Observaciones y seguimiento']];return `<div class="page"><div class="pageHead"><div><h1>Libro de Clases 3.0</h1><p>Objeto familiar, datos vivos. La estructura física se conserva, pero recibe información desde asistencia, planificación, evaluación, PIE y seguimiento.</p></div><div class="actions"><button class="btn" onclick="bookSpread=Math.max(0,bookSpread-1);render()">←</button><button class="btn blue" onclick="bookSpread=Math.min(4,bookSpread+1);render()">→ Hojear</button></div></div><div class="bookDesk"><div class="bookShell"><div class="bookBack"></div><div class="spine"></div>${bookPages(spreads[bookSpread],bookSpread)}<div class="bookControls"><button class="turn" onclick="bookSpread=Math.max(0,bookSpread-1);render()">‹</button><div class="bookIndicator">Páginas ${bookSpread*2+1}–${bookSpread*2+2} · ${spreads[bookSpread][0]}</div><button class="turn" onclick="bookSpread=Math.min(4,bookSpread+1);render()">›</button></div></div></div></div>`;}
function bookPages(titles,i){const rows=db.students.slice(0,15).map((s,j)=>`<tr><td>${j+1}</td><td>${s.name}</td><td>${i===2?s.today:i===4?s.avg:'2° Medio B'}</td></tr>`).join('');const rows2=db.students.slice(15).map((s,j)=>`<tr><td>${j+16}</td><td>${s.name}</td><td>${i===2?s.today:i===4?s.avg:'Apoderado registrado'}</td></tr>`).join('');return `<div class="bookSpread"><section class="paper left"><div class="watermark">LIBRO<br>4.0</div><h2>${titles[0]}</h2>${i===0?`<div class="paperInfo"><div class="line"><b>Establecimiento</b><span>${db.school.name}</span></div><div class="line"><b>RBD</b><span>${db.school.rbd}</span></div><div class="line"><b>Curso</b><span>${db.school.course}</span></div><div class="line"><b>Profesor(a) jefe</b><span>${db.school.teacher}</span></div></div>`:`<table class="paperTable"><thead><tr><th>N°</th><th>Estudiante</th><th>${i===2?'Asistencia':i===4?'Promedio':'Dato'}</th></tr></thead><tbody>${rows}</tbody></table>`}<span class="pageNum">${i*2+1}</span></section><section class="paper right"><div class="watermark">LIBRO<br>4.0</div><h2>${titles[1]}</h2>${i===0?`<table class="paperTable"><thead><tr><th>N°</th><th>Sección</th><th>Pág.</th></tr></thead><tbody>${['Nómina','Asistencia','Leccionario','Evaluaciones','Observaciones','PIE / apoyos'].map((x,k)=>`<tr><td>${k+1}</td><td>${x}</td><td>${3+k*2}</td></tr>`).join('')}</tbody></table><div class="paperInfo" style="margin-top:10px"><div class="line"><b>Total estudiantes</b><span>30</span></div><div class="line"><b>Año</b><span>${db.school.year}</span></div></div>`:`<table class="paperTable"><thead><tr><th>N°</th><th>Estudiante</th><th>${i===2?'Asistencia':i===4?'Seguimiento':'Dato'}</th></tr></thead><tbody>${rows2}</tbody></table>`}<span class="pageNum">${i*2+2}</span></section></div>`;}

function curriculumPage(){const level=LEVELS.find(x=>x.id===db.ui.currLevel)||LEVELS[0];const subjects=SUBJECTS[level.track]||[];if(!subjects.includes(db.ui.currSubject))db.ui.currSubject=subjects[0];const data=CURRICULUM.filter(x=>x.levelId===level.id&&x.subject===db.ui.currSubject);return `<div class="page"><div class="pageHead"><div><h1>Currículum, OA y competencias</h1><p>La navegación cubre Educación Parvularia, Básica, Media HC y Media TP. Los OA mostrados son ejemplos DEMO: la arquitectura está diseñada para importar y versionar el catálogo oficial completo.</p></div><div class="actions"><span class="badge warn">OA DEMO estructurados</span></div></div><div class="sourceStrip"><b>Modelo curricular:</b> OA → contenidos → competencias/habilidades → indicadores → instrumentos → estrategias → inicio/desarrollo/cierre → recursos → tiempo y espacio. La versión productiva debe conservar fuente, vigencia y texto oficial del Mineduc.</div><div class="curriculumMap" style="margin-top:12px">${LEVELS.map(l=>`<div class="levelChip ${l.id===level.id?'active':''}" onclick="db.ui.currLevel='${l.id}';db.ui.currSubject='${(SUBJECTS[l.track]||[])[0]}';save();render()"><b>${l.name}</b><small>${l.track}</small></div>`).join('')}</div><div class="toolbar" style="margin-top:12px"><select class="field" onchange="db.ui.currSubject=this.value;save();render()">${subjects.map(s=>`<option ${s===db.ui.currSubject?'selected':''}>${s}</option>`).join('')}</select>${level.track==='Técnico-Profesional'?`<select class="field">${TP_SPECIALTIES.map(x=>`<option>${x}</option>`).join('')}</select>`:''}</div>${data.map(oa=>oaDetail(oa)).join('')}</div>`;}
function oaDetail(oa){return `<div class="oaCard"><div class="cardHead"><div><div class="oaCode">${oa.id} · ${oa.level} · ${oa.subject}</div><h4>${oa.unit}</h4></div><button class="btn tiny" onclick="selectedOA=CURRICULUM.find(x=>x.id==='${oa.id}');go('planificador')">Usar en planificación</button></div><p><b>OA / propósito:</b> ${oa.objective}</p><div class="pedagogyGrid" style="margin-top:10px"><div class="pedBox"><h4>Contenidos · ¿qué enseñar?</h4><p>${oa.content}</p></div><div class="pedBox"><h4>Competencias / habilidades</h4><ul>${oa.competencies.map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="pedBox"><h4>Indicadores e instrumentos</h4><ul>${oa.indicators.map(x=>`<li>${x}</li>`).join('')}</ul><p><b>Instrumentos:</b> ${oa.instruments.join(', ')}</p></div><div class="pedBox"><h4>Estrategias y organización didáctica</h4><p>${oa.strategy}</p></div></div><div class="phaseGrid" style="margin-top:8px"><div class="phase"><b>Inicio</b><p>${oa.phases.start}</p></div><div class="phase"><b>Desarrollo</b><p>${oa.phases.development}</p></div><div class="phase"><b>Cierre</b><p>${oa.phases.closure}</p></div></div><div class="pedagogyGrid" style="margin-top:8px"><div class="pedBox"><h4>Recursos y medios didácticos</h4><p>${oa.resources.join(' · ')}</p></div><div class="pedBox"><h4>Tiempo y espacio</h4><p>${oa.timeSpace}</p></div></div></div>`;}

function plannerPage(){
 const levelId=db.ui.plannerLevel||selectedOA?.levelId||'2M';
 const level=LEVELS.find(x=>x.id===levelId)||LEVELS.find(x=>x.id==='2M')||LEVELS[0];
 const subjects=SUBJECTS[level.track]||[];
 let subject=db.ui.plannerSubject||selectedOA?.subject||subjects[0];
 if(!subjects.includes(subject)) subject=subjects[0];
 const oas=CURRICULUM.filter(x=>x.levelId===level.id&&x.subject===subject);
 let oaId=db.ui.plannerOA||selectedOA?.id||oas[0]?.id;
 let oa=oas.find(x=>x.id===oaId)||oas[0]||CURRICULUM[0];
 selectedOA=oa;
 db.ui.plannerLevel=level.id; db.ui.plannerSubject=subject; db.ui.plannerOA=oa.id;
 return `<div class="page"><div class="pageHead"><div><h1>Planificador pedagógico</h1><p>Selecciona primero el curso y la asignatura. El sistema muestra únicamente los OA disponibles para esa combinación y utiliza el OA elegido para completar contenidos, competencias, indicadores, estrategias, recursos y estructura de la clase.</p></div><div class="actions"><button class="btn" onclick="go('curriculum')">Explorar currículum</button><button class="btn blue" onclick="savePlan()">Guardar planificación</button></div></div>
 <div class="plannerCascade"><div><label>1 · Curso / nivel</label><select class="field" onchange="plannerLevelChanged(this.value)">${LEVELS.map(l=>`<option value="${l.id}" ${l.id===level.id?'selected':''}>${l.name}</option>`).join('')}</select></div><div><label>2 · Asignatura / núcleo</label><select class="field" onchange="plannerSubjectChanged(this.value)">${subjects.map(x=>`<option ${x===subject?'selected':''}>${x}</option>`).join('')}</select></div><div class="oaPicker"><label>3 · Objetivo de Aprendizaje</label><select class="field" onchange="plannerOAChanged(this.value)">${oas.map(x=>`<option value="${x.id}" ${x.id===oa.id?'selected':''}>${x.id} · ${x.unit}</option>`).join('')}</select><small>${esc(oa.objective)}</small></div></div>
 ${level.track==='Técnico-Profesional'?`<div class="sourceStrip" style="margin-top:10px"><b>Especialidad TP:</b> <select class="inlineSelect">${TP_SPECIALTIES.map(x=>`<option>${x}</option>`).join('')}</select> · El OA/competencia seleccionado debe vincularse a desempeño técnico observable.</div>`:''}
 <div class="flowHint"><span>Curso</span><b>→</b><span>Asignatura</span><b>→</b><span>OA</span><b>→</b><span>Planificación</span><b>→</b><span>Evaluación</span></div>
 <div class="grid cols2"><div class="card"><div class="cardHead"><h3>Contexto curricular</h3><span class="badge blue">${oa.level} · ${oa.subject}</span></div><label>OA seleccionado</label><textarea id="plOA" class="field" style="min-height:76px">${esc(oa.objective)}</textarea><label>Contenidos · ¿qué enseñar?</label><textarea id="plContent" class="field">${esc(oa.content)}</textarea><label>Competencias / habilidades</label><input id="plComp" class="field" value="${esc(oa.competencies.join(', '))}"><label>Indicadores de evaluación</label><textarea id="plInd" class="field">${esc(oa.indicators.join(' · '))}</textarea><label>Instrumento / evidencia sugerida</label><select id="plInst" class="field">${oa.instruments.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="card"><div class="cardHead"><h3>Estrategias y organización didáctica</h3><span class="badge ok">DUA</span></div><label>Inicio</label><textarea id="plStart" class="field">${esc(oa.phases.start)}</textarea><label>Desarrollo</label><textarea id="plDev" class="field">${esc(oa.phases.development)}</textarea><label>Cierre</label><textarea id="plClose" class="field">${esc(oa.phases.closure)}</textarea><label>Recursos / medios didácticos</label><input id="plResources" class="field" value="${esc(oa.resources.join(' + '))}"><label>Organización del tiempo y espacio</label><input id="plTime" class="field" value="${esc(oa.timeSpace)}"><label>Adecuaciones / DUA / co-docencia</label><textarea id="plDUA" class="field">Múltiples formas de representación, participación y expresión. Ajustar consignas, apoyos, tiempos y formas de respuesta según barreras detectadas.</textarea></div></div><div class="card" style="margin-top:14px"><div class="cardHead"><h3>Planificaciones registradas</h3><span class="badge">${db.plans.length}</span></div><div class="tableWrap"><table><thead><tr><th>Nivel</th><th>Asignatura</th><th>OA</th><th>Título</th><th>Estado UTP</th></tr></thead><tbody>${db.plans.map(p=>`<tr><td>${p.level}</td><td>${p.subject}</td><td>${p.oa||'—'}</td><td>${p.title}</td><td>${p.status}</td></tr>`).join('')}</tbody></table></div></div></div>`;
}
function plannerLevelChanged(id){db.ui.plannerLevel=id;const l=LEVELS.find(x=>x.id===id)||LEVELS[0];db.ui.plannerSubject=(SUBJECTS[l.track]||[])[0];const oa=CURRICULUM.find(x=>x.levelId===id&&x.subject===db.ui.plannerSubject);db.ui.plannerOA=oa?.id;selectedOA=oa||selectedOA;save();render();}
function plannerSubjectChanged(subject){db.ui.plannerSubject=subject;const oa=CURRICULUM.find(x=>x.levelId===db.ui.plannerLevel&&x.subject===subject);db.ui.plannerOA=oa?.id;selectedOA=oa||selectedOA;save();render();}
function plannerOAChanged(id){db.ui.plannerOA=id;selectedOA=CURRICULUM.find(x=>x.id===id)||selectedOA;save();render();}
function savePlan(){db.plans.push({id:Date.now(),level:selectedOA.level,subject:selectedOA.subject,oa:selectedOA.id,title:`Planificación ${selectedOA.unit}`,status:db.user.profile==='utp'?'Aprobada':'Pendiente UTP',teacher:db.user.name,start:val('plStart'),development:val('plDev'),closure:val('plClose'),content:val('plContent'),competencies:val('plComp'),indicators:val('plInd'),instrument:val('plInst'),resources:val('plResources'),timeSpace:val('plTime'),dua:val('plDUA')});db.audit.push({time:now(),actor:db.user.name,event:'Planificación creada',detail:`${selectedOA.level} · ${selectedOA.subject}`});save();render();}

function evaluationPage(){
 const levelId=db.ui.evalLevel||selectedOA?.levelId||'2M';
 const level=LEVELS.find(x=>x.id===levelId)||LEVELS.find(x=>x.id==='2M')||LEVELS[0];
 const subjects=SUBJECTS[level.track]||[];
 let subject=db.ui.evalSubject||selectedOA?.subject||subjects[0]; if(!subjects.includes(subject))subject=subjects[0];
 const oas=CURRICULUM.filter(x=>x.levelId===level.id&&x.subject===subject);
 let oa=oas.find(x=>x.id===(db.ui.evalOA||selectedOA?.id))||oas[0]||CURRICULUM[0];
 selectedOA=oa; db.ui.evalLevel=level.id; db.ui.evalSubject=subject; db.ui.evalOA=oa.id;
 const tab=db.ui.evalTab||'crear';
 const current=db.instruments.find(x=>x.id===(db.ui.correctionInstrument||db.instruments[db.instruments.length-1]?.id))||db.instruments[db.instruments.length-1];
 return `<div class="page"><div class="pageHead"><div><h1>Evaluaciones</h1><p>Un solo espacio para diseñar el instrumento, generarlo desde el OA seleccionado y posteriormente corregirlo. El corrector queda asociado al instrumento para conservar trazabilidad pedagógica.</p></div></div>
 <div class="evalTabs"><button class="evalTab ${tab==='crear'?'active':''}" onclick="setEvalTab('crear')">🧪 Crear instrumento</button><button class="evalTab ${tab==='corregir'?'active':''}" onclick="setEvalTab('corregir')">✅ Corregir instrumento</button><button class="evalTab ${tab==='historial'?'active':''}" onclick="setEvalTab('historial')">🗂 Historial</button></div>
 ${tab==='crear'?`<div class="grid cols2"><div class="card"><div class="cardHead"><h3>1. Parámetros curriculares</h3><span class="badge blue">OA → instrumento</span></div><div class="evalCascade"><div><label>1 · Curso / nivel</label><select class="field" onchange="evalLevelChanged(this.value)">${LEVELS.map(l=>`<option value="${l.id}" ${l.id===level.id?'selected':''}>${l.name}</option>`).join('')}</select></div><div><label>2 · Asignatura / núcleo</label><select class="field" onchange="evalSubjectChanged(this.value)">${subjects.map(x=>`<option ${x===subject?'selected':''}>${x}</option>`).join('')}</select></div><div><label>3 · Objetivo de Aprendizaje</label><select class="field" onchange="evalOAChanged(this.value)">${oas.map(x=>`<option value="${x.id}" ${x.id===oa.id?'selected':''}>${x.id} · ${x.unit}</option>`).join('')}</select><small>${esc(oa.objective)}</small></div></div><div class="oaSelected"><b>OA seleccionado</b><span>${esc(oa.objective)}</span></div><label>Indicadores / criterios</label><textarea id="evCrit" class="field">${esc(oa.indicators.join(' · '))}</textarea></div><div class="card"><div class="cardHead"><h3>2. Diseño del instrumento</h3><span class="badge ok">Generación parametrizada</span></div><div class="grid equal2"><div><label>Tipo de instrumento</label><select id="evType" class="field"><option>Prueba mixta</option><option>Rúbrica analítica</option><option>Lista de cotejo</option><option>Proyecto</option><option>Evaluación de desempeño TP</option></select></div><div><label>Cantidad de ítems</label><select id="evCount" class="field"><option>8</option><option selected>10</option><option>15</option><option>20</option></select></div><div><label>Nivel de dificultad</label><select id="evDifficulty" class="field"><option>Inicial</option><option selected>Intermedio</option><option>Desafiante</option></select></div><div><label>Propósito</label><select id="evPurpose" class="field"><option>Diagnóstica</option><option selected>Formativa</option><option>Sumativa</option></select></div><div><label>Ponderación</label><select id="evWeight" class="field"><option>10%</option><option>20%</option><option selected>30%</option><option>40%</option></select></div><div><label>Exigencia</label><select id="evThreshold" class="field"><option>50%</option><option selected>60%</option><option>70%</option></select></div></div><label style="margin-top:10px"><input id="evAdapt" type="checkbox"> Crear además versión flexibilizada / adecuación evaluativa</label><div class="privacyNotice" style="margin-top:10px">La versión flexibilizada puede reducir carga de ítems, segmentar instrucciones, incorporar apoyo visual, ampliar tiempos o habilitar otra forma de respuesta. Debe responder al perfil autorizado del estudiante.</div><button class="btn blue full" style="margin-top:12px" onclick="generateInstrument()">Generar instrumento con estos parámetros</button></div></div><div id="instrumentPreview"></div>`:
 tab==='corregir'?evaluationCorrector(current):evaluationHistory()}
 </div>`;
}
function setEvalTab(tab){db.ui.evalTab=tab;save();render();}
function evalLevelChanged(id){db.ui.evalLevel=id;const l=LEVELS.find(x=>x.id===id)||LEVELS[0];db.ui.evalSubject=(SUBJECTS[l.track]||[])[0];const oa=CURRICULUM.find(x=>x.levelId===id&&x.subject===db.ui.evalSubject);db.ui.evalOA=oa?.id;selectedOA=oa||selectedOA;save();render();}
function evalSubjectChanged(subject){db.ui.evalSubject=subject;const oa=CURRICULUM.find(x=>x.levelId===db.ui.evalLevel&&x.subject===subject);db.ui.evalOA=oa?.id;selectedOA=oa||selectedOA;save();render();}
function evalOAChanged(id){db.ui.evalOA=id;selectedOA=CURRICULUM.find(x=>x.id===id)||selectedOA;save();render();}
function evaluationCorrector(inst){if(!inst)return `<div class="workbenchPanel"><h3>Corrector integrado</h3><div class="empty">Primero crea un instrumento. Al generarlo podrás pasar directamente a su corrección.</div></div>`;return `<div class="grid cols2"><div class="card"><div class="cardHead"><h3>Instrumento a corregir</h3><span class="badge blue">${esc(inst.subject)}</span></div><label>Instrumento</label><select class="field" onchange="db.ui.correctionInstrument=Number(this.value);save();render()">${db.instruments.map(i=>`<option value="${i.id}" ${i.id===inst.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select><div class="assessmentSummary"><b>${esc(inst.name)}</b><span>${esc(inst.level)} · ${esc(inst.subject)} · ${inst.questions} ítems · ${inst.difficulty||'Intermedio'} · exigencia ${inst.threshold||'60%'}</span><small>OA: ${esc(inst.oa||'')}</small></div><label>Estudiante</label><select id="corrStudent" class="field">${db.students.map(s=>`<option>${s.name}</option>`).join('')}</select><label>Respuesta selección múltiple</label><select id="corr1" class="field"><option value="0">A</option><option value="1">B</option><option value="2">C</option></select><label>Respuesta de desarrollo</label><textarea id="corrText" class="field" style="min-height:120px">La respuesta explica el procedimiento utilizado y relaciona la evidencia con el objetivo trabajado.</textarea><button class="btn blue full" style="margin-top:10px" onclick="runCorrection()">Corregir con criterios del instrumento</button></div><div class="card" id="corrResult"><div class="cardHead"><h3>Resultado y retroalimentación</h3><span class="badge">Docente valida</span></div><div class="empty">Ejecuta la corrección. El sistema mostrará logro, puntaje y una sugerencia de retroalimentación vinculada al OA.</div></div></div>`;}
function evaluationHistory(){return `<div class="workbenchPanel"><div class="cardHead"><h3>Instrumentos creados</h3><span class="badge ok">${db.instruments.length}</span></div>${db.instruments.slice().reverse().map(i=>`<div class="row"><div class="rowText"><b>${esc(i.name)}</b><small>${esc(i.level)} · ${esc(i.subject)} · OA ${esc(i.oa||'—')} · ${i.questions} ítems · ${i.type||'Prueba mixta'} · ${i.purpose||'Formativa'}</small></div><div class="actionRow"><span class="pill ${i.status.includes('Validado')?'green':'amber'}">${i.status}</span><button class="btn tiny" onclick="db.ui.correctionInstrument=${i.id};db.ui.evalTab='corregir';save();render()">Corregir</button></div></div>`).join('')||'<div class="empty">Aún no hay instrumentos.</div>'}</div>`;}
function generateInstrument(){
 const adapted=document.getElementById('evAdapt')?.checked;
 const oa=CURRICULUM.find(x=>x.id===db.ui.evalOA)||selectedOA||CURRICULUM[0];
 selectedOA=oa;
 const inst={id:Date.now(),name:`${adapted?'Versión adaptada · ':''}${oa.subject} · ${oa.level} · ${new Date().toLocaleDateString('es-CL')}`,level:oa.level,levelId:oa.levelId,subject:oa.subject,oa:oa.id,oaText:oa.objective,criteria:val('evCrit'),adapted,questions:Number(val('evCount'))||10,type:val('evType')||'Prueba mixta',difficulty:val('evDifficulty')||'Intermedio',purpose:val('evPurpose')||'Formativa',weight:val('evWeight')||'30%',threshold:val('evThreshold')||'60%',status:db.user.profile==='utp'?'Validado UTP':'Pendiente validación UTP'};
 db.instruments.push(inst); db.ui.correctionInstrument=inst.id;
 db.audit.push({time:now(),actor:db.user.name,event:'Instrumento generado',detail:`${inst.level} · ${inst.subject} · ${inst.oa} · ${inst.type}`}); save();
 const preview=document.getElementById('instrumentPreview'); if(!preview)return;
 const sampleCount=Math.min(inst.questions,6);
 const stems=['Selecciona la alternativa que mejor demuestra el aprendizaje esperado.','Aplica el concepto en una situación nueva y justifica tu decisión.','Analiza la evidencia presentada y determina la respuesta más pertinente.','Relaciona el contenido con un caso contextualizado.','Explica el procedimiento utilizado y verifica el resultado.','Propón una solución y argumenta utilizando los criterios del OA.'];
 preview.innerHTML=`<div class="card instrumentSheet" style="margin-top:14px"><div class="cardHead"><div><span class="eyebrow">VISTA PREVIA DEL INSTRUMENTO</span><h3>${esc(inst.name)}</h3></div><span class="badge ${adapted?'warn':'blue'}">${adapted?'Flexibilizada':'Estándar'}</span></div><div class="instrumentMeta"><span>${esc(inst.type)}</span><span>${inst.questions} ítems</span><span>${esc(inst.difficulty)}</span><span>${esc(inst.purpose)}</span><span>Exigencia ${esc(inst.threshold)}</span><span>Ponderación ${esc(inst.weight)}</span></div><div class="oaSelected"><b>${esc(inst.oa)}</b><span>${esc(inst.oaText)}</span></div>${buildInstrumentBody(inst,oa,stems)}<div class="feedback"><b>Criterios:</b> ${esc(inst.criteria)}</div><div class="actionRow"><button class="btn" onclick="window.print()">Imprimir / PDF</button><button class="btn blue" onclick="db.ui.evalTab='corregir';save();render()">Ir al corrector de este instrumento</button></div></div>`;
}

function buildInstrumentBody(inst,oa,stems){
 const count=Math.min(inst.questions,6);
 const diff=inst.difficulty==='Inicial'?'con apoyo y contexto familiar':inst.difficulty==='Desafiante'?'en una situación nueva que exige justificar y transferir':'en una situación contextualizada';
 if(inst.type==='Rúbrica analítica') return `<table class="rubricMini"><thead><tr><th>Criterio</th><th>Inicial</th><th>En desarrollo</th><th>Logrado</th><th>Destacado</th></tr></thead><tbody>${oa.indicators.slice(0,4).map((c,i)=>`<tr><td>${esc(c)}</td><td>Evidencia incipiente</td><td>Logro parcial</td><td>Cumple el criterio</td><td>Profundiza y transfiere</td></tr>`).join('')}</tbody></table><div class="feedback" style="margin-top:10px">Producto/tarea: evidencia de desempeño ${diff}. Propósito: ${esc(inst.purpose)}.</div>`;
 if(inst.type==='Lista de cotejo') return `<div class="checklistPreview">${oa.indicators.concat(['Utiliza recursos pertinentes','Comunica el proceso y resultado']).slice(0,count).map((c,i)=>`<div class="row"><div class="rowText"><b>☐ ${esc(c)}</b><small>Criterio ${i+1} · ${diff}</small></div><span class="pill">Sí / No</span></div>`).join('')}</div>`;
 if(inst.type==='Proyecto'||inst.type==='Evaluación de desempeño TP') return `<div class="projectBrief"><div class="question"><div class="qnum">Desafío / producto</div><h4>Desarrolla una tarea auténtica vinculada a ${esc(inst.oa)} ${diff}.</h4><p class="subtle">El producto debe evidenciar: ${esc(oa.indicators.join(' · '))}</p></div><div class="grid equal2"><div class="pedBox"><h4>Proceso</h4><p>Planifica, ejecuta, registra evidencias y ajusta el procedimiento.</p></div><div class="pedBox"><h4>Producto</h4><p>Entrega una evidencia observable alineada al OA y criterios seleccionados.</p></div></div></div>`;
 return Array.from({length:count},(_,i)=>`<div class="question"><div class="qnum">${i+1} · ${i<Math.ceil(count*.65)?'Selección / respuesta breve':'Desarrollo'}</div><h4>${esc(stems[i%stems.length])} ${esc(diff)}.</h4>${i<Math.ceil(count*.65)?'<div class="option">A. Alternativa plausible</div><div class="option">B. Alternativa correcta DEMO</div><div class="option">C. Distractor vinculado a error frecuente</div>':'<div class="answerLines"></div>'}</div>`).join('');
}

function correctorPage(){db.ui.evalTab='corregir';route='evaluaciones';return evaluationPage();}
function runCorrection(){
 const inst=db.instruments.find(x=>x.id===Number(db.ui.correctionInstrument))||db.instruments[db.instruments.length-1]; if(!inst)return;
 const student=val('corrStudent'); const objectiveScore=val('corr1')==='1'?4:2; const dev=val('corrText'); const developmentScore=dev.length>90?4:dev.length>40?3:2; const score=objectiveScore+developmentScore; const pct=Math.round(score/8*100); const threshold=parseInt(inst.threshold)||60; const achieved=pct>=threshold;
 db.corrections.push({student,instrument:inst.name,instrumentId:inst.id,oa:inst.oa,score,pct,time:now(),validated:false}); db.audit.push({time:now(),actor:db.user.name,event:'Corrección ejecutada',detail:`${student} · ${inst.name} · ${pct}%`}); save();
 document.getElementById('corrResult').innerHTML=`<div class="cardHead"><h3>Resultado</h3><span class="badge ${achieved?'ok':'warn'}">${achieved?'Logro esperado':'Requiere refuerzo'}</span></div><div class="corrScore">${pct}%</div><p><b>${student}</b> · ${score}/8 puntos · exigencia ${esc(inst.threshold||'60%')}</p><div class="criteriaResult"><div><b>Respuesta objetiva</b><span>${objectiveScore}/4</span></div><div><b>Desarrollo / argumentación</b><span>${developmentScore}/4</span></div><div><b>OA evaluado</b><span>${esc(inst.oa||'')}</span></div></div><div class="feedback"><b>Retroalimentación sugerida:</b><br>${achieved?'La respuesta evidencia comprensión del OA. Se sugiere profundizar la justificación y transferir el aprendizaje a un nuevo contexto.':'Se observa aprendizaje parcial. Reforzar el concepto central, modelar un ejemplo y solicitar una nueva evidencia de desempeño.'}</div><div class="scopeNotice" style="margin-top:10px"><b>Control humano:</b> la calificación oficial y la retroalimentación final deben ser validadas por el docente conforme a la pauta/rúbrica del instrumento.</div>`;
}
function resourcesPage(){return `<div class="page"><div class="pageHead"><div><h1>Biblioteca pedagógica</h1><p>Actividades, presentaciones, guías, material didáctico, videos y apoyos DUA/PIE organizados por nivel, asignatura y OA.</p></div></div><div class="resourceGrid">${db.resources.map(r=>`<div class="resource"><div class="resourceThumb ${r.type==='Video'?'video':r.type==='Presentación'?'presentation':r.type.includes('didáctico')?'didactic':''}">${r.icon}</div><div class="resourceBody"><div class="resourceMeta"><span class="badge blue">${r.type}</span><span class="badge">${r.level}</span></div><h4>${r.title}</h4><p>${r.desc}</p><div class="actions" style="margin-top:9px"><button class="btn tiny" onclick="alert('Recurso agregado a planificación DEMO')">Agregar a planificación</button><button class="btn tiny" onclick="alert('Vista previa DEMO')">Vista previa</button></div></div></div>`).join('')}</div></div>`;}

