function switchProfile(v){
 if(!PROFILE_CONFIG[v]) return;
 db.user={...db.user,profile:v,name:PROFILE_CONFIG[v].name};
 route='inicio';
 db.audit.push({time:now(),actor:'DEMO',event:'Cambio de perfil',detail:PROFILE_CONFIG[v].label});
 save();render();
}
function setWorkbench(area,value){db.ui=db.ui||{};db.ui[area+'Tab']=value;save();render();}
function demoAction(event,detail){db.audit.push({time:now(),actor:db.user.name,event,detail});save();alert(detail+' · acción registrada en la DEMO.');}

function shell(){
 const options=Object.entries(PROFILE_CONFIG).map(([k,p])=>`<option value="${k}" ${db.user.profile===k?'selected':''}>${p.label}</option>`).join('');
 return `<div class="shell ${profileClass()}">${navHtml()}<main class="main"><header class="topbar"><div class="crumb"><b>${ROUTES[route]?.[1]||'Ecosistema 4.2'}</b><small>${cfg().tag}</small></div><div class="topActions"><span class="versionBadge">4.2 · OA + EVALUACIÓN + LIBRETA</span><div class="profileSwitcher"><label>Probar perfil</label><select onchange="switchProfile(this.value)">${options}</select></div><span class="sync"><i></i> Sincronizado</span><button class="btn small" onclick="resetDemo41()">Reiniciar</button><div class="user"><div class="avatar">${initials(db.user.name)}</div><div class="utxt"><b style="font-size:11px">${db.user.name}</b><small>${cfg().label}</small></div></div></div></header>${pageFor(route)}</main></div>`;
}

function navHtml(){
 const grouped={};cfg().routes.filter(r=>r!=='inicio').forEach(r=>{const g=ROUTES[r][2];(grouped[g]??=[]).push(r)});
 return `<aside class="sidebar"><div class="sideBrand"><div class="brandMark"></div><div class="brandText"><b>Ecosistema 4.2</b><small>${cfg().label}</small></div></div><div class="navGroup"><button class="navItem ${route==='inicio'?'active':''}" onclick="go('inicio')"><span class="navIcon">⌂</span><span class="navText">Inicio</span></button></div>${Object.entries(grouped).map(([g,rs])=>`<div class="navGroup"><div class="navLabel">${g}</div>${rs.map(r=>`<button class="navItem ${route===r?'active':''}" onclick="go('${r}')"><span class="navIcon">${ROUTES[r][0]}</span><span class="navText">${ROUTES[r][1]}</span></button>`).join('')}</div>`).join('')}<div class="sideFoot">DEMO 4.2 · OA, evaluación y libreta ampliada<br>Datos ficticios · permisos demostrativos.<br><button class="navItem" onclick="logout()"><span class="navIcon">↪</span><span class="navText">Cerrar sesión</span></button></div></aside>`;
}

function pageFor(r){const f={inicio:homePage,perfil:profilePage,libro:bookPage,planificador:plannerPage,curriculum:curriculumPage,evaluaciones:evaluationPage,corrector:correctorPage,recursos:resourcesPage,pie:piePage,utp:utpPage,inspectoria:inspectoriaPage,convivencia:convivenciaPage,protocolos:protocolsPage,rfid:rfidPage,retiros:withdrawalPage,estudiantes:studentsPage,comunidad:communityPage,libreta:libretaPage,familia:familyPage,reportes:reportsPage}[r];return f?f():homePage();}

function profilePage(){
 const rs=ROLE_RESPONSIBILITIES[db.user.profile]||[]; const p=PROFILE_SUMMARY[db.user.profile];
 const allowed=cfg().routes.filter(x=>!['inicio','perfil'].includes(x));
 return `<div class="page"><div class="profileHero"><div><span class="eyebrow" style="color:#fff9">PERFIL ACTIVO · ${cfg().label}</span><h2>${p.title}</h2><p>${p.desc}</p><div class="actionRow"><button class="btn" onclick="go('inicio')">Ir al inicio</button>${db.user.profile==='sostenedor'?'<button class="btn" onclick="go(\'reportes\')">Control Tower</button>':''}</div></div><div class="scope">${p.metrics.map(m=>`<div><b>${m[0]}</b><small>${m[1]}</small></div>`).join('')}</div></div><div class="sectionLabel">Responsabilidades y tareas</div><div class="responsibilityGrid">${rs.map(r=>`<div class="responsibility"><div class="ricon">${r[0]}</div><div><b>${r[1]}</b><small>${r[2]}</small></div></div>`).join('')}</div><div class="sectionLabel">Módulos habilitados para este perfil</div><div class="roleMap">${allowed.map(r=>`<div class="roleMapCard"><h4>${ROUTES[r][0]} ${ROUTES[r][1]}</h4><p>${routeDescription(r)}</p><div class="actionRow"><button class="btn tiny" onclick="go('${r}')">Abrir módulo</button></div></div>`).join('')}</div><div class="scopeNotice" style="margin-top:14px"><b>Regla de acceso:</b> en producción estas atribuciones deben validarse en servidor (RBAC/ABAC). La DEMO las representa visualmente para probar la experiencia de cada perfil.</div></div>`;
}
function routeDescription(r){return ({libro:'Libro físico-digital, asistencia, leccionario y evidencia.',planificador:'Planificación completa por OA y organización didáctica.',curriculum:'Catálogo por nivel, asignatura, OA y competencias.',evaluaciones:'Selección por curso/asignatura/OA, creación parametrizada y corrector integrado.',corrector:'Corrector integrado al creador de evaluaciones.',recursos:'Biblioteca de actividades, guías, presentaciones, videos y material.',pie:'Evaluación integral, DUA, PACI, co-docencia y apoyos.',utp:'Cobertura, revisión, acompañamiento y validación.',inspectoria:'RIE, asistencia, seguridad, retiros y logística.',convivencia:'Prevención, mediación, participación y redes.',protocolos:'Rutas de actuación, responsables y seguimiento.',rfid:'Presence Engine, excepciones y firma.',retiros:'Registro seguro de salida durante la jornada.',estudiantes:'Trayectoria longitudinal autorizada.',comunidad:'Comunicaciones y participación segmentadas.',libreta:'Canal bidireccional familia–escuela.',familia:'Información exclusiva de hijos/as asociados.',reportes:'Control Tower y excepciones de red.'}[r]||'Módulo del ecosistema.');}

function homePage(){
 if(db.user.profile==='apoderado') return familyPage(true);
 const p=PROFILE_SUMMARY[db.user.profile]; const resp=ROLE_RESPONSIBILITIES[db.user.profile]||[];
 const primary={docente:['libro','planificador','evaluaciones','recursos'],diferencial:['pie','planificador','evaluaciones','libreta'],utp:['utp','curriculum','evaluaciones','pie'],inspectoria:['inspectoria','rfid','retiros','protocolos'],convivencia:['convivencia','protocolos','comunidad','libreta'],sostenedor:['reportes','libro','utp','pie']}[db.user.profile]||[];
 return `<div class="page"><div class="profileHero"><div><span class="eyebrow" style="color:#fff9">${cfg().label.toUpperCase()}</span><h2>${p.title}</h2><p>${p.desc}</p><div class="actionRow"><button class="btn" onclick="go('perfil')">Ver todas mis atribuciones</button></div></div><div class="scope">${p.metrics.map(m=>`<div><b>${m[0]}</b><small>${m[1]}</small></div>`).join('')}</div></div><div class="sectionLabel">Acciones principales de este perfil</div><div class="taskGrid">${primary.map(r=>task(ROUTES[r][0],ROUTES[r][1],routeDescription(r),r)).join('')}</div><div class="grid cols2" style="margin-top:14px"><div class="card"><div class="cardHead"><h3>Responsabilidades del perfil</h3><button class="btn tiny" onclick="go('perfil')">Ver detalle</button></div><div class="detailList">${resp.slice(0,5).map(r=>`<div class="detailItem"><b>${r[0]} ${r[1]}</b><p>${r[2]}</p></div>`).join('')}</div></div><div class="card"><div class="cardHead"><h3>Flujo compartido del ecosistema</h3><span class="badge blue">Dato único</span></div><div class="flow" style="margin-top:8px"><span class="flowStep">OA</span><span class="flowArrow">→</span><span class="flowStep">Planificación</span><span class="flowArrow">→</span><span class="flowStep">Clase</span><span class="flowArrow">→</span><span class="flowStep">Evaluación</span><span class="flowArrow">→</span><span class="flowStep">Libro</span><span class="flowArrow">→</span><span class="flowStep">Familia / Gestión</span></div><div class="scopeNotice" style="margin-top:12px">La intención es evitar dobles registros: lo planificado alimenta el libro; lo evaluado alimenta resultados; asistencia y retiros alimentan Inspectoría y familia; PIE agrega apoyos autorizados.</div></div></div></div>`;
}

