 if(tab==='paci') content=`<div class="workbenchPanel"><h3>Diseño de adecuaciones curriculares</h3><p>Construcción y seguimiento de PACI, priorización de objetivos, adecuaciones de acceso y flexibilización de instrumentos.</p><div class="grid cols2"><div class="card"><h3>PACI activos</h3>${db.paci.map(p=>`<div class="row"><div class="rowText"><b>${p.student}</b><small>${p.goal}<br><b>Adecuación:</b> ${p.adaptation}<br>Revisión: ${p.review}</small></div><span class="pill amber">seguimiento</span></div>`).join('')}<button class="btn tiny" onclick="demoAction('PACI','Nuevo PACI de demostración creado')">+ Nuevo PACI</button></div><div class="card"><h3>Flexibilización de evaluación</h3>${['Menor cantidad de ítems','Instrucciones segmentadas','Apoyo visual / pictográfico','Material concreto','Tiempo adicional','Respuesta oral o multimodal'].map(x=>`<div class="row"><div class="rowText"><b>${x}</b><small>Ajuste disponible para instrumento adaptado</small></div><span class="pill green">disponible</span></div>`).join('')}<button class="btn tiny" onclick="go('evaluaciones')">Crear evaluación adaptada</button></div></div></div>`;
 if(tab==='recursos') content=`<div class="workbenchPanel"><h3>Apoyo especializado · Aula de recursos</h3><p>Intervenciones individuales o en grupos pequeños orientadas a habilidades descendidas y funciones de base.</p><div class="grid cols3">${[['Lectoescritura','Conciencia fonológica, fluidez, comprensión y producción.'],['Cálculo','Sentido numérico, estrategias y resolución de problemas.'],['Funciones ejecutivas','Planificación, memoria de trabajo, inhibición y flexibilidad.'],['Autorregulación','Rutinas, anticipación, regulación emocional y conducta.'],['Comunicación','Apoyos visuales, lenguaje y participación.'],['Habilidades adaptativas','Autonomía, organización y acceso al entorno.']].map(x=>`<div class="card"><h3>${x[0]}</h3><p class="subtle">${x[1]}</p><button class="btn tiny" onclick="demoAction('Intervención PIE','Sesión de ${x[0]} registrada')">Registrar sesión</button></div>`).join('')}</div></div>`;
