 if(tab==='seguridad') content=`<div class="workbenchPanel"><h3>Seguridad, higiene y planta física</h3><p>PISE, simulacros, emergencias, auxiliares, infraestructura y supervisión de espacios comunes.</p><div class="grid cols3">${[['🚨','PISE','Próximo simulacro 29/03 · 11:30'],['🧹','Aseo y servicios','Turnos completos · 1 incidencia'],['🔧','Infraestructura','2 mantenimientos abiertos'],['🏫','Recreos','Turnos de patio asignados'],['🍽️','Comedor','Refuerzo de supervisión'],['🩺','Emergencia médica','Botiquines revisados']].map(x=>`<div class="card"><h3>${x[0]} ${x[1]}</h3><p class="subtle">${x[2]}</p><button class="btn tiny" onclick="demoAction('Inspectoría','${x[1]} actualizado')">Registrar</button></div>`).join('')}</div></div>`;
 if(tab==='familia') content=`<div class="workbenchPanel"><h3>Vinculación y continuidad directiva</h3><p>Atención a apoderados, compromisos firmados y continuidad de información para subrogación cuando corresponda.</p><div class="grid cols2"><div class="card"><h3>Atención a apoderados</h3>${['Entrevista por asistencia','Compromiso por puntualidad','Citación por convivencia'].map(x=>`<div class="detailItem"><b>${x}</b><p>Acta, acuerdos, firma y fecha de seguimiento.</p></div>`).join('')}<button class="btn tiny" onclick="go('libreta')">Comunicar por libreta</button></div><div class="card"><h3>Subrogación / continuidad</h3><p class="subtle">Panel de asuntos críticos, reemplazos, incidentes, protocolos y decisiones pendientes para asegurar continuidad operativa.</p><div class="scopeNotice">En producción, la facultad de subrogación depende de la estructura y normativa interna del establecimiento; la plataforma solo organiza la información autorizada.</div></div></div></div>`;
