 if(tab==='intervencion') content=`<div class="workbenchPanel"><h3>Intervención, mediación y activación de protocolos</h3><p>Mediación, arbitraje pedagógico, negociación, medidas de apoyo y seguimiento compartido con Inspectoría.</p><div class="grid cols2"><div class="card"><h3>Mediaciones</h3>${db.convivenciaCases.map(c=>`<div class="row"><div class="rowText"><b>${c.student} · ${c.type}</b><small>${c.status}<br>${c.next}</small></div><button class="btn tiny" onclick="demoAction('Mediación','Seguimiento de ${c.student}')">Seguimiento</button></div>`).join('')}</div><div class="card"><h3>Protocolos</h3>${db.protocols.filter(p=>p.type==='Convivencia').map(p=>`<div class="detailItem"><b>${p.title}</b><p>${p.status} · ${p.stage}</p></div>`).join('')}<button class="btn tiny" onclick="go('protocolos')">Abrir rutas de actuación</button></div></div></div>`;
 if(tab==='equipo') content=`<div class="workbenchPanel"><h3>Coordinación del equipo y redes externas</h3><p>Liderazgo del comité, coordinación interdisciplinaria, derivaciones y asesoría al cuerpo docente.</p><div class="grid cols3">${[['👥','Comité de Convivencia','Psicología, trabajo social, orientación y psicopedagogía.'],['🌐','Redes externas','Salud, protección de derechos, tribunales u otras redes autorizadas.'],['🎓','Asesoría docente','Herramientas para consejo de curso, contención y resolución de conflictos.']].map(x=>`<div class="card"><h3>${x[0]} ${x[1]}</h3><p class="subtle">${x[2]}</p><button class="btn tiny" onclick="demoAction('Convivencia','${x[1]} registrado')">Registrar</button></div>`).join('')}</div></div>`;
